const githubUrl = $json.submission.github_url || '';
const parts = githubUrl.replace(/\/$/, '').split('/');
const repo = parts.pop() || '';
const owner = parts.pop() || '';

return {
  owner,
  repo,
  has_github: !!(owner && repo),
  submission_id: $json.submission_id,
  user_id: $json.user_id,
  challenge: $json.challenge,
  submission: $json.submission,
  phase1_score: $json.phase1_score,
  phase1_signals: $json.phase1_signals,
  callback_url: $json.callback_url
};

const filesData = $('Fetch GitHub Contents').all().map(item => item.json);
const commitsData = $('Fetch GitHub Commits').all().map(item => item.json);
const readmeData = $('Fetch GitHub README').all().map(item => item.json);

const mainInput = $('Parse GitHub URL').item.json;

// Format files list
const fileList = Array.isArray(filesData[0]) 
  ? filesData[0].map(f => `- ${f.path} (${f.type})`).join('\n')
  : 'No files retrieved.';

// Format recent commits
const recentCommits = Array.isArray(commitsData[0])
  ? commitsData[0].slice(0, 5).map(c => `- [${c.sha.slice(0, 7)}] ${c.commit.message} by ${c.commit.author.name} on ${c.commit.author.date}`).join('\n')
  : 'No commits found.';

// Raw readme content
let readmeContent = typeof readmeData[0] === 'string' 
  ? readmeData[0] 
  : (readmeData[0] && readmeData[0].content ? readmeData[0].content : 'No README content found.');

return {
  ...mainInput,
  github_file_list: fileList,
  readme_content: readmeContent,
  recent_commits: recentCommits
};

parameters.text:
=You are a technical project validator for a developer habit-building app.

Your job is to evaluate whether a submitted project genuinely completes
the given challenge or is still a work in progress.

---
CHALLENGE:
Title: {{ $json.challenge.title }}
Description: {{ $json.challenge.description }}
Expected Deliverables: {{ $json.challenge.expected_deliverables }}
Difficulty: {{ $json.challenge.difficulty }}

---
SUBMISSION EVIDENCE:

GitHub Repository Contents:
{{ $json.github_file_list }}

README Content:
{{ $json.readme_content }}

Recent Commits (last 5):
{{ $json.recent_commits }}

User's Written Description:
{{ $json.submission.proof_text }}

Phase 1 Rule Signals:
{{ $json.phase1_signals }}

---
EVALUATION CRITERIA:

1. RELEVANCE — Does the project actually address the challenge brief?
2. COMPLETENESS — Is there working functionality, not just scaffolding?
3. EFFORT — Does the commit history and code volume show real work?
4. DOCUMENTATION — Is there any README or description explaining what was built?

---
Respond ONLY with a valid JSON object. No explanation outside the JSON.

{
  "verdict": "complete" | "in_progress" | "insufficient",
  "confidence": 0-100,
  "score": 0-100,
  "criteria_scores": {
    "relevance": 0-100,
    "completeness": 0-100,
    "effort": 0-100,
    "documentation": 0-100
  },
  "feedback": "2-3 sentence explanation shown to the user",
  "internal_notes": "1 sentence reasoning for your verdict",
  "missing_elements": ["list", "of", "what's", "missing"]
}

parameters.jsCode:
let responseText = $json.output || $json.text || '';
// Strip markdown code fences if LLM wraps output in ```json ... ```
responseText = responseText.trim().replace(/^```json/, '').replace(/```$/, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(responseText);
} catch (e) {
  parsed = {
    verdict: "insufficient",
    confidence: 30,
    score: 20,
    feedback: "Could not parse evaluation format structure from AI agent output.",
    missing_elements: ["Valid AI response structure"]
  };
}

return {
  submission_id: $('Prepare Prompt').item.json.submission_id,
  verdict: parsed.verdict || "insufficient",
  confidence: parsed.confidence || 0,
  score: parsed.score || 0,
  criteria_scores: parsed.criteria_scores || { relevance: 0, completeness: 0, effort: 0, documentation: 0 },
  feedback: parsed.feedback || "Evaluation verdict concluded by validator node.",
  missing_elements: parsed.missing_elements || []
};
